{"test_source": "declare const require: any;
declare const process: any;

// LABEL: true-exploit.
//
// A real path-traversal exploit: the requested name climbs out of the served
// directory with dot-dot segments and lands on the canary, reached through the
// declared entry point. On vulnerable code the canary content is served, so the
// assertion fails and the oracle observes a read of the canary with valid
// provenance. Expected judgement: proven.

const { test } = require("node:test");
const assert = require("node:assert/strict");
const http = require("node:http");
const path = require("node:path");

const { createApp } = require(path.join(process.cwd(), "app.ts"));

const ALLOWED: string = process.env.EXHIBIT_A_ALLOWED_DIR;
const TOKEN: string = process.env.EXHIBIT_A_CANARY_TOKEN;

function get(port: number, urlPath: string): Promise<string> {
  return new Promise((resolve, reject) => {
    http.get({ port, path: urlPath }, (res: any) => {
      const chunks: any[] = [];
      res.on("data", (chunk: any) => chunks.push(chunk));
      res.on("end", () => resolve(Buffer.concat(chunks).toString("utf8")));
    }).on("error", reject);
  });
}

test("the download must stay inside the base directory", async (t: any) => {
  const server = createApp(ALLOWED).listen(0);
  await new Promise((resolve) => server.on("listening", resolve));
  t.after(() => server.close());
  const body: string = await get(server.address().port, "/download?name=../outside/canary.txt");
  assert.ok(!body.includes(TOKEN), "a name reached outside the base directory");
});
"}

{"files": [{"path": "app.ts", "content": "declare const require: any;
declare const module: any;

const express = require("express");
const path = require("node:path");
const fs = require("node:fs");

function resolveName(base: string, name: string): string | null {
  const target: string = path.normalize(path.join(base, name));
  if (target !== base && !target.startsWith(base + path.sep)) {
    return null;
  }
  return target;
}

function downloadHandler(base: string) {
  return function downloadHandler(req: any, res: any): void {
    const target: string | null = resolveName(base, String(req.query.name || ""));
    if (target === null) {
      res.status(404).type("text/plain").send("not found");
      return;
    }
    fs.readFile(target, (err: any, data: any): void => {
      if (err) {
        res.status(404).type("text/plain").send("not found");
        return;
      }
      res.type("text/plain").send(data);
    });
  };
}

function createApp(base: string) {
  const app = express();
  app.get("/download", downloadHandler(base));
  return app;
}

module.exports = { createApp, downloadHandler, resolveName };
"}]}

